class Dashboard extends StatelessWidget{const Dashboard({super.key});Future<_Data> load()async{final db=AppDatabase.instance;return _Data(await db.accounts(),await db.transactions(),await db.setting('company'),await db.setting('currency'));}@override Widget build(BuildContext c)=>FutureBuilder<_Data>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!,e=AccountingEngine(),b=e.trialBalance(d.accounts,d.txs),income=e.incomeStatement(b),bs=e.balanceSheet(b);double total(String k)=>bs[k]!.last.amount;final net=income.last.amount;return ListView(padding:const EdgeInsets.all(18),children:[Text(d.company,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const Text('Resumen financiero',style:TextStyle(color:Colors.blueGrey)),const SizedBox(height:16),Wrap(spacing:10,runSpacing:10,children:[Kpi('Utilidad neta',net,d.currency,Icons.trending_up),Kpi('Activos',total('Activos'),d.currency,Icons.account_balance_wallet),Kpi('Pasivos',total('Pasivos'),d.currency,Icons.payments_outlined),Kpi('Patrimonio',total('Patrimonio')+net,d.currency,Icons.savings_outlined)]),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const DailyPositionPage())),icon:const Icon(Icons.today),label:const Text('Ver posición diaria'))),const SizedBox(height:18),const Text('Comprobaciones',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),CheckTile('Débitos = Créditos',b.fold<double>(0,(s,x)=>s+x.debit),b.fold<double>(0,(s,x)=>s+x.credit)),CheckTile('Activos = Pasivos + Patrimonio',total('Activos'),total('Pasivos')+total('Patrimonio')+net),const SizedBox(height:14),Card(color:const Color(0xffecfeff),child:Padding(padding:const EdgeInsets.all(16),child:Text(d.txs.isEmpty?'Aún no hay transacciones. Entra en Diario y pulsa + para registrar el primer asiento.':'Hay ${d.txs.length} transacciones registradas. Todos los estados