class Kpi extends StatelessWidget{final String t,c;final double v;final IconData i;const Kpi(this.t,this.v,this.c,this.i,{super.key});@override Widget build(BuildContext x)=>SizedBox(width:(MediaQuery.sizeOf(x).width-48)/2,child:Card(color:const Color(0xfff0f9ff),child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i,color:const Color(0xff0369a1)),const SizedBox(height:10),Text(t),Text('$c ${v.toStringAsFixed(2)}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17))]))));}
class CheckTile extends StatelessWidget{final String t;final double a,b;const CheckTile(this.t,this.a,this.b,{super.key});@override Widget build(BuildContext c){final ok=(a-b).abs()<.01;return ListTile(contentPadding:EdgeInsets.zero,leading:Icon(ok?Icons.check_circle:Icons.warning,color:ok?Colors.green:Colors.orange),title:Text(t),subtitle:Text('${a.toStringAsFixed(2)} / ${b.toStringAsFixed(2)}'));}}

