class TransactionForm extends StatefulWidget{const TransactionForm({super.key});@override State<TransactionForm>createState()=>_TransactionFormState();}
class _TransactionFormState extends State<TransactionForm>{final desc=TextEditingController(),ref=TextEditingController();DateTime date=DateTime.now();String cls='operating';List<Account> accounts=[];final lines=<Map<String,dynamic>>[{'account':null,'debit':'','credit':''},{'account':null,'debit':'','credit':''}];@override void initState(){super.initState();AppDatabase.instance.accounts().then((v)=>setState(()=>accounts=v));}double n(dynamic x)=>double.tryParse('$x'.replaceAll(',',''))??0;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Nuevo asiento')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descripción',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:ref,decoration:const InputDecoration(labelText:'Referencia / factura',border:OutlineInputBorder())),const SizedBox(height:10),DropdownButtonFormField(value:cls,decoration:const InputDecoration(labelText:'Clasificación de efectivo',border:OutlineInputBorder()),items:const [DropdownMenuItem(value:'operating',child:Text('Operativa')),DropdownMenuItem(value:'investing',child:Text('Inversión')),DropdownMenuItem(value:'financing',child:Text('Financiamiento')),DropdownMenuItem(value:'noncash',child:Text('Sin efectivo'))],onChanged:(v)=>setState(()=>cls=v!)),const SizedBox(height:16),const Text('Débitos y créditos',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),...List.generate(lines.length,(i)=>Card(child:Padding(padding:const EdgeInsets.all(10),child:Column(children:[DropdownButtonFormField<int>(value:lines[i]['account'],isExpanded:true,decoration:const InputDecoration(labelText:'Cuenta'),items:accounts.map((a)=>DropdownMenuItem(value:a.id,child:Text('${a.code} · ${a.name}'))).toList(),onChanged:(v)=>lines[i]['account']=v),Row(children:[Expanded(child:TextFormField(key:ValueKey('d$i'),keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Débito'),onChanged:(v)=>lines[i]['debit']=v)),const SizedBox(width:12),Expanded(child:TextFormField(key:ValueKey('c$i'),keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Crédito'),onChanged:(v)=>lines[i]['credit']=v))])]))),TextButton.icon(onPressed:()=>setState(()=>lines.add({'account':null,'debit':'','credit':''})),icon:const Icon(Icons.add),label:const Text('Añadir línea')),FilledButton.icon(onPressed:()async{try{final tx=JournalTransaction(date:date,description:desc.text,reference:ref.text,cashFlowClass:cls,lines:lines.map((l)=>JournalLine(accountId:l['account']??-1,debit:n(l['debit']),credit:n(l['credit']))).toList());await AppDatabase.instance.addTransaction(tx);if(c.mounted)Navigator.pop(c,true);}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('$e')));}},icon:const Icon(Icons.save),label:const Text('Guardar asiento'))]));}}

class Reports extends StatelessWidget{const Reports({super.key});Future<_Data> load()async{final db=AppDatabase.instance;return _Data(await db.accounts(),await db.transactions(),await db.setting('company'),await db.setting('currency'));}@override Widget build(BuildContext c)=>FutureBuilder<_Data>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!,e=AccountingEngine(),b=e.trialBalance(d.accounts,d.txs),inc=e.incomeStatement(b),bs=e.balanceSheet(b),cash=e.cashFlow(d.accounts,d.txs),eq=e.equityStatement(b);final reports=<String,List<ReportRow>>{'Estado de Resultados':inc,'Balance General':[...bs['Activos']!,...bs['Pasivos']!,...bs['Patrimonio']!,ReportRow('RESULTADO DEL PERÍODO',inc.last.amount,total:true)],'Flujo de Efectivo':cash,'Cambios en el Patrimonio':eq,'Balance de Comprobación':b.where((x)=>x.debit!=0||x.credit!=0).map((x)=>ReportRow('${x.account.code} ${x.account.name} · D ${x.debit.toStringAsFixed(2)} / C ${x.credit.toStringAsFixed(2)}',x.signed)).toList()};return DefaultTabController(length:reports.length,child:Scaffold(appBar:AppBar(title:const Text('Estados financieros'),bottom:TabBar(isScrollable:true,tabs:reports.keys.map((x)=>Tab(text:x)).toList())),body:TabBarView(children:reports.entries.map((r)=>ReportView(title:r.key,rows:r.value,data:d)).toList())));});}
